// CSD_RATIONALE_BEGIN
// Analysis of previous failure: 0 examples evaluated suggests a compilation/runtime error,
// likely caused by the `EnterObservedConstrainedSpan` call pattern or the double-step
// in Phase 3 (CloseSpanIfComplete + SafeRepetitionPenaltyStep in same iteration violating
// invariants), or the `if maxSteps == 0` branch structure.
//
// Key design decisions for this attempt:
// 1. Use GenerateWithPrefixAndManagedSpan as the high-level helper - it handles all
//    delimiter management, parser control, and span closing internally with verified
//    proof obligations. This avoids hand-written loops with potential issues.
// 2. Set prefixBudget to allow reasonable free-text reasoning before forcing span entry.
// 3. Add task guidance to steer the model toward the correct output format.
// 4. The helper handles: free generation -> << detection -> constrained generation ->
//    >> closing, all within maxSteps budget.
// 5. This avoids the "multiple << spans" problem by design - GenerateWithPrefixAndManagedSpan
//    manages span state internally.
// 6. For GSM symbolic math: the parser likely accepts arithmetic expressions.
//    We want most budget for reasoning, then force constrained span for the answer.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   GenerateWithPrefixAndManagedSpan's postcondition directly guarantees:
//   !insideConstrainedOut ==> currentConstrainedOut == [] and
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   These are the exact invariants required. Preserved by helper contract.
//
// progress: |generated| <= |generatedPrefix| + maxSteps
//   GenerateWithPrefixAndManagedSpan's postcondition guarantees cost <= maxSteps
//   and |generated| <= |generatedPrefix| + maxSteps. Since we pass maxSteps directly,
//   the bound holds. We set cost := maxSteps which satisfies cost <= maxSteps.
//   The progress postcondition (cost > 0 || generated != generatedPrefix || ...) is
//   satisfied because when maxSteps > 0 the helper takes at least 1 step.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve the math problem step by step. Write all reasoning freely. At the very end, place exactly one final numeric answer inside << >> delimiters. Example: <<42>>. Use only the constrained span for the final answer number.";
  helpers.AppendTaskGuidance(lm, guidance);

  // Use prefixBudget to allow reasoning before forcing span entry
  // Reserve enough budget for the constrained answer span (at least 10 steps)
  var prefixBudget: nat := maxSteps;
  if maxSteps > 20 {
    prefixBudget := maxSteps - 10;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 4.0, 12, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;
  cost := maxSteps;
}

// CSD_RATIONALE_BEGIN
// Analysis of failures:
// 1. The model generates correct reasoning but puts wrong expressions in << >>
//    - e.g., "n - n * frac" instead of "n - int(n * frac)" 
//    - The constrained span content is syntactically wrong (contains {}, **)
// 2. The constrained activity shows: 23/49 examples used constrained decoding,
//    but ALL 23 with activity were WRONG. The 8 correct ones had NO constrained activity.
// 3. This means the constrained generation is actively hurting accuracy - the model's
//    free-text reasoning produces better answers than the constrained span.
// 4. The issue: the model writes the answer in free text first, then the constrained
//    span gets generated separately (often incorrectly or with syntax errors).
//
// Root cause: The model is being forced to re-generate the answer inside << >> via
// constrained decoding, but the constrained decoder is generating different (wrong)
// tokens compared to what the model would naturally emit.
//
// Strategy for this attempt:
// 1. Use UnconstrainedChunk to let the model generate freely, watching for "<<".
// 2. When "<<" is detected (stoppedOnOpenSpan), use EnterObservedConstrainedSpan
//    to enter constrained mode WITHOUT appending another "<<".
// 3. Inside the span, use SafeRepetitionPenaltyStep to avoid repeating tokens,
//    and CloseSpanIfComplete to close as soon as the parser is satisfied.
// 4. Use a smaller chunk size (10-15 tokens) so we don't miss the "<<" delimiter.
// 5. The key insight: let the model's natural generation find "<<" via UnconstrainedChunk,
//    then use ConstrainedStep ONLY to enforce valid tokens while following the model's intent.
// 6. Guide the model to produce simple arithmetic expressions like "n1*p1 + n2*p2".
//    The parser likely validates these. Use SafeTemperatureConstrainedStep with low
//    temperature to sharpen the model's natural choice.
// 7. Use CloseSpanWithinBudget after entering the span to ensure termination.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   - Phase 1 (UnconstrainedChunk): When stoppedOnOpenSpan, generated already ends with "<<"
//     and EnterObservedConstrainedSpan sets insideConstrainedOut:=true, currentConstrainedOut:=[].
//     [] is a valid prefix by parser.IsValidPrefix([]) precondition.
//   - Phase 1 (no open span): insideConstrainedOut remains false, implication vacuous.
//   - Phase 2 (CloseSpanWithinBudget): postcondition guarantees
//     !insideConstrainedOut ==> currentConstrainedOut == [] and
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   All transitions preserve the invariant.
//
// progress: |generated| <= |generatedPrefix| + steps
//   - Phase 1: UnconstrainedChunk postcondition: |generatedOut| <= |generated| + stepsUsed,
//     steps += stepsUsed. So |generated| <= |generatedPrefix| + steps.
//   - Phase 2: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated_before| + closeBudget,
//     and closeBudget = maxSteps - steps. So total |generated| <= |generatedPrefix| + maxSteps.
//     We set steps := maxSteps. Bound preserved.
//   - EOS branch in Phase 1: generated is not extended, steps only grows.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve the math problem step by step using the symbolic variables. Write the final answer as a simple arithmetic expression using only the variable names (no {}, no **, no markdown). Put the final expression inside << >>. Example: <<n1 * p1 + n2 * p2>>.";
  helpers.AppendTaskGuidance(lm, guidance);

  var steps: nat := 0;

  // Phase 1: Generate freely in small chunks, watching for "<<" opening delimiter
  // Use small chunks (15 tokens) to reliably detect "<<"
  var chunkSize: nat := 15;

  while steps < maxSteps && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var remaining := maxSteps - steps;
    var thisChunk := chunkSize;
    if remaining < thisChunk {
      thisChunk := remaining;
    }
    if thisChunk == 0 {
      break;
    }

    var genOut, stoppedOnOpen, stoppedOnEos, stepsUsed :=
      helpers.UnconstrainedChunk(lm, prompt, generated, thisChunk, "<<", eosToken);
    steps := steps + stepsUsed;
    generated := genOut;

    if stoppedOnEos {
      break;
    } else if stoppedOnOpen {
      // "<<" was already appended by UnconstrainedChunk; enter span state without re-appending
      var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
      // insideConstrainedOut is now true, loop exits
    }
    // else: no open span and no EOS, continue generating
  }

  // Phase 2: If inside a constrained span, use CloseSpanWithinBudget to finish it
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Analysis of failures:
// 1. Best result (16.3% accuracy, 89.8% syntax) used GenerateWithPrefixAndManagedSpan.
// 2. Previous attempt regressed to 0% by switching to UnconstrainedChunk + EnterObservedConstrainedSpan,
//    which caused repetition loops and runtime errors.
// 3. The main remaining failure modes from the best attempt:
//    - syntax_valid_semantic_mismatch: 36 examples (correct syntax, wrong answer)
//    - The model generates syntax-valid but semantically wrong expressions
// 4. Key insight from rollouts: The model correctly reasons in free text, but the
//    constrained span captures the wrong expression (e.g., adds "- 1" repetitions,
//    copies intermediate values instead of the final answer).
// 5. Strategy: Use GenerateWithPrefixAndManagedSpan as the base (proven best), but
//    improve guidance to be more explicit about the output format.
// 6. The repetition issue in constrained spans (e.g., "- 1 - 1 - 1...") suggests the
//    parser allows these and the model falls into a loop. Use SafeRepetitionPenaltyStep
//    logic by leveraging AdaptiveConstrainedStep with a larger boost to help the model
//    close the span sooner.
// 7. Use a smaller prefixBudget to force the span entry earlier, ensuring the model
//    has budget to complete the span properly before hitting max_steps.
// 8. Keep the approach simple: GenerateWithPrefixAndManagedSpan handles all span logic
//    internally with verified proofs. Adjust parameters and guidance only.
// 9. The guidance should emphasize: write the answer as a SINGLE simple expression,
//    no repeated subtractions, use the variable names from the problem.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   GenerateWithPrefixAndManagedSpan's postcondition directly guarantees:
//   !insideConstrainedOut ==> currentConstrainedOut == [] and
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   These invariants are preserved by the helper contract without any additional proof work.
//
// progress: |generated| <= |generatedPrefix| + maxSteps
//   GenerateWithPrefixAndManagedSpan's postcondition guarantees:
//   cost <= maxSteps and |generated| <= |generatedPrefix| + maxSteps.
//   We set cost := maxSteps which trivially satisfies cost <= maxSteps.
//   When maxSteps > 0, the helper takes at least 1 step (cost > 0), satisfying
//   the non-trivial progress postcondition.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve the math problem using the symbolic variable names given. Think step by step. At the very end, write exactly one expression inside << >> using ONLY the variable names and basic arithmetic operators (+, -, *, /). The expression must be simple and complete on one line. Do NOT repeat terms or add/subtract the same value multiple times. Example: <<n * frac_1 * frac_2>> or <<p1 + p2 - d>>.";
  helpers.AppendTaskGuidance(lm, guidance);

  // Allow most of the budget for free reasoning, but reserve enough for the constrained answer.
  // Using a smaller prefixBudget ensures the model is forced into the constrained span
  // with sufficient remaining budget to complete and close it.
  var prefixBudget: nat := maxSteps;
  if maxSteps > 50 {
    prefixBudget := maxSteps - 50;
  } else if maxSteps > 20 {
    prefixBudget := maxSteps - 10;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 4.0, 12, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;
  cost := maxSteps;
}

// CSD_RATIONALE_BEGIN
// Diagnosis of failures:
// 1. The model generates correct free-text reasoning but the constrained span captures wrong/malformed content.
// 2. Two main failure categories:
//    a. malformed_constrained_content (4 examples): span contains {}, **, or unparseable content
//       - The model uses template syntax like {cur}{initial_amount} inside the span
//       - Root cause: the model writes the expression in its free-text style with curly braces
//       - Fix: use strict parser-controlled generation inside the span with hard masking
//    b. unterminated_constrained_segment (2 examples): span opened but not closed
//       - The model opens << but doesn't generate >> before hitting budget/EOS
//       - Fix: use CloseSpanWithinBudget to force closure
// 3. syntax_valid_semantic_mismatch (34 examples): correct syntax but wrong answer
//    - The model often arrives at the right answer in free text but writes a different/simplified expression in the span
//    - The guidance should be clearer: write the LAST expression you computed as the answer
//    - Key insight: most correct answers are simple arithmetic on variable names, NOT {cur}-prefixed
//    - The model is confused by {cur} prefix notation - it thinks the variable name includes {cur}
//    - Need to clarify that variable names are the plain names (initial_amount, not {cur}{initial_amount})
// 4. Strategy: 
//    a. Use strong guidance to clarify variable naming (no curly braces, no {cur} prefix)
//    b. Use GenerateWithPrefixAndManagedSpan as the base (proven reliable structure)
//    c. After generation, if still inside constrained span, force close with CloseSpanWithinBudget
//    d. Use a moderate prefixBudget to allow sufficient reasoning before forcing span entry
// 5. The key insight is that `used_constrained: no (100%)` in mode_B (15 examples) means the
//    model is generating spans that look valid but without constrained intervention - the parser
//    is not actually controlling those tokens. This suggests GenerateWithPrefixAndManagedSpan
//    is letting the model emit spans freely without proper parser control.
// 6. New approach: use a manual loop with strict span control:
//    - Free generation until "<<" is observed
//    - Once inside span, use ONLY ConstrainedStep (hardest parser control)
//    - Use CloseSpanIfComplete to close as soon as possible
//    - Use CloseSpanWithinBudget at the end to force closure
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Phase 1 (unconstrained): Only transitions to insideConstrainedOut=true when next=="<<",
//   setting currentConstrainedOut := [] which satisfies parser.IsValidPrefix([]) by precondition.
//   Phase 2 (constrained): CloseSpanIfComplete either closes span (making implication vacuous with
//   insideConstrainedOut=false) or leaves state unchanged. ConstrainedStep returns only parser-valid
//   tokens or EOS, and AppendConstrainedToken preserves parser validity. The closing phase uses
//   CloseSpanWithinBudget whose postcondition guarantees both invariants.
//
// progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedStep costs 1 step and appends at most 1 token, so each iteration
//   increments steps by 1 while generated grows by at most 1. Invariant preserved.
//   Phase 2: Each iteration of the constrained loop increments steps by 1 (CloseSpanIfComplete
//   costs 1 when closing, ConstrainedStep costs 1), and appends at most 1 token. Invariant preserved.
//   CloseSpanWithinBudget postcondition guarantees |generated| <= |generated_before| + budget
//   and budget = maxSteps - steps, so total |generated| <= |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve the math problem step by step. Use the plain variable names from the problem (without curly braces or currency prefixes). At the very end, write your final answer inside << >> using ONLY plain variable names and operators +, -, *, /. Example: <<n * price - discount>> NOT <<{n} * {cur}{price}>>. No curly braces inside << >>. One expression only.";
  helpers.AppendTaskGuidance(lm, guidance);

  var steps: nat := 0;

  // Phase 1: Free generation until we enter a constrained span
  while steps < maxSteps && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }

  // Phase 2: Constrained generation inside the span with hard parser control
  while steps < maxSteps && insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Try to close if complete
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      // Use strict constrained step - hard parser control only
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }

  // Phase 3: Force close if still inside span with remaining budget
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Diagnosis of current failures:
// 1. mode_J (9 examples): No << >> span emitted, hit max steps. The model spends all 900 steps
//    in free generation without ever writing <<. Fix: use a strict budget for free generation,
//    then force entry into constrained mode and use CloseSpanWithinBudget.
// 2. mode_G (16 examples): Syntax valid but wrong answer, used_constrained=no. The constrained
//    span is being generated freely (the model just writes it without parser control). This means
//    the "<<" detection in Phase 1 is catching the span after the model already wrote it, and
//    Phase 2's constrained loop never fires.
// 3. mode_D (2 examples): final_span_invalid with {}, ** syntax. The model writes invalid
//    expressions inside the span.
//
// Key insight from diagnostic: "Constrained intervention activity: examples_with_activity 5/49"
// This means only 5/49 examples actually used constrained generation! The other 44 had the
// model write << >> freely in unconstrained mode, bypassing parser control entirely.
//
// Root cause: In Phase 1 (unconstrained loop), the model writes the entire "<<expr>>" span
// in one burst. By the time we detect "<<" and set insideConstrainedOut=true, the model has
// already emitted ">>" and the full expression in prior UnconstrainedStep calls. So we never
// enter Phase 2.
//
// Fix strategy:
// 1. Use a SHORT free generation budget (e.g., 800 steps) for reasoning
// 2. Then FORCE open a constrained span explicitly with OpenConstrainedSpan
// 3. Generate the constrained content with hard parser control (ConstrainedStep)
// 4. Close with CloseSpanWithinBudget
// 5. Use guidance that tells the model NOT to write << >> in its reasoning - only use it
//    at the explicit forced insertion point
//
// This ensures constrained generation always fires for the answer span.
// The free generation budget must be large enough for reasoning (most examples use ~100-400 tokens)
// but leave room for the constrained span (at least ~20 steps for expression + close).
//
// For the entered_constrained_mode_too_early issue: with OpenConstrainedSpan forced after
// free generation, we avoid this.
//
// For malformed content (** operator): the parser hard-masks invalid tokens, so ** cannot appear.
//
// The guidance should tell the model: write your reasoning, then STOP - do not write << >>.
// The system will automatically insert the answer span after reasoning.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Phase 1 (free reasoning): insideConstrainedOut stays false throughout this loop (we break
//   when insideConstrainedOut would become true, i.e., we don't transition). Actually we just
//   run unconstrained and check for EOS. insideConstrainedOut remains false = implication vacuous.
//   OpenConstrainedSpan: sets insideConstrainedOut=true, currentConstrainedOut=[] which satisfies
//   parser.IsValidPrefix([]) by precondition. So invariant holds.
//   Phase 2 (constrained): CloseSpanIfComplete either closes (insideConstrainedOut=false, vacuous)
//   or leaves state unchanged. ConstrainedStep returns parser-valid token or EOS; AppendConstrainedToken
//   preserves parser.IsValidPrefix(currentConstrainedOut) since next was validated. CloseSpanWithinBudget
//   postcondition guarantees insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: each UnconstrainedStep increments steps by 1 and appends at most 1 token.
//   OpenConstrainedSpan: increments steps by 1 and appends 1 token ("<<"), so still preserved.
//   Phase 2: CloseSpanIfComplete costs 1 step and appends at most 1 token (">>" on close).
//   ConstrainedStep costs 1 step; AppendConstrainedToken appends 1 token but costs 0 steps.
//   So each constrained iteration: steps+1, |generated|+1. Invariant preserved.
//   CloseSpanWithinBudget: budget = maxSteps - steps, postcondition |generated| <= old|generated| + budget,
//   and we set steps := maxSteps, so |generated| <= |generatedPrefix| + maxSteps. Preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve the math problem step by step using plain variable names (no curly braces, no ** operator, no dollar signs in variable names). Write your complete reasoning. Do NOT write << or >> yourself - the answer will be inserted automatically after your reasoning ends.";
  helpers.AppendTaskGuidance(lm, guidance);

  var steps: nat := 0;

  // Reserve budget for constrained span: need at least 20 steps for expression + close
  var reservedForSpan: nat := 20;
  var freeReasoningBudget: nat := if maxSteps > reservedForSpan then maxSteps - reservedForSpan else 0;

  // Phase 1: Free reasoning generation
  // Run unconstrained until we hit the budget limit, EOS, or the model prematurely opens a span
  while steps < freeReasoningBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases freeReasoningBudget - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if next == "<<" {
      // Model prematurely opened span - enter it properly
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }

  // Phase 2: If not already inside a span, force open one
  if !insideConstrainedOut && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;
  }

  // Phase 3: Hard constrained generation inside the span
  while steps < maxSteps && insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Try to close if complete
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      // Hard constrained step - strict parser control
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }

  // Phase 4: Force close if still inside span with remaining budget
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Analysis of failures from best attempt (accuracy 30.6%, syntax 77.6%):
// 1. Primary issue: 15/49 unterminated spans. The span is opened but CloseSpanWithinBudget
//    runs out of budget because Phase 1 consumes too many tokens (~237 avg before first "<<").
//    With 900 steps total, ~680 steps remain when "<<" appears on average, which should be enough.
//    But the issue is that Phase 2 ConstrainedStep loop runs until maxSteps, not leaving budget
//    for CloseSpanWithinBudget. Actually Phase 3 (CloseSpanWithinBudget) IS called with remaining
//    budget - so why are spans not closing?
//
// 2. Key insight from diagnostics: "Visible span token length: avg 3.15, median 1.00"
