// and be in constrained mode when it's about to write the SECOND "<<" (the final one).
// But wait - the model might write the final "<<" at the same time as the first.
// "output tail: '...The final answer is <<n1 * frac + n2>>.'" - this is AT token ~229!
//
// OK so the model writes "The final answer is <<expr>>" all at once at token ~229-255.
// There's no second "<<". So if we skip early "<<" detection (threshold=350), we MISS
// the only "<<" and never enter constrained mode!
//
// CONCLUSION: The model writes "<<expr>>" at token ~229. We detect "<<" at token ~229.
// We enter constrained mode. The constrained loop generates "expr". CloseSpanWithinBudget closes.
// This should work and IS what attempt 27 does (getting 26.5%).
//
// The 8 unclosed spans in attempt 38 are due to the EOS penalization keeping the model
// generating PAST the valid expression endpoint, consuming the CloseSpanWithinBudget budget.
//
// CLEANEST FIX: Remove EOS penalization entirely. Use attempt 27's approach but with
// CloseSpanIfComplete per step (not just on EOS) to close the span ASAP.
//
// Also fix: when ConstrainedStep returns a non-valid token (token not recognized as valid),
// don't append it. The current code uses IsTokenValidNext check.
//
// PLAN (close to attempt 27 but with per-step CloseSpanIfComplete):
// Phase 1: Free gen until "<<" OR reasoningBudget
// Phase 2: Constrained loop with CloseSpanIfComplete FIRST each iteration
// Phase 3: CloseSpanWithinBudget
//
// Per-step CloseSpanIfComplete prevents the scenario where the span stays open because
// ConstrainedStep never returns EOS (due to infinite loop in the constrained space).
//
// BUDGET ALLOCATION:
// - Free generation: up to 600 tokens (to let model write reasoning + "<<")
// - Constrained: remaining budget (~300 tokens)
// - CloseSpanWithinBudget: at least 50 tokens reserved
//
// This matches attempt 27 which got 26.5% (best so far).
//
// IMPROVEMENT OVER ATTEMPT 27:
// 1. CloseSpanIfComplete at EACH step (not just on EOS)
//    -> Closes span sooner when expression is already complete
// 2. Better guidance (no curly braces in expression)
//    -> Reduces malformed_constrained_content failures
// 3. Reserve budget for CloseSpanWithinBudget
//    -> Reduces unclosed spans
//
// GUIDANCE IMPROVEMENT:
// From rollout: model writes "<<t * {currency} * {frac1} + ({total} - t) * {currency} * {frac2}>>"
// The {currency} is being treated as a variable! The guidance should say:
// "In the final expression, do NOT include currency symbols or unit variables like {cur}.
//  Only include numeric computation variables."
// Actually the issue is the model includes "{currency}" as a var, which is invalid.
// Better guidance: "Use ONLY the variable names shown in the problem WITHOUT curly braces.
//  Do not include currency prefixes, unit names, or format strings."
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (free generation loop):
//   - When next != "<<" and next != eosToken: generated grows by 1, insideConstrainedOut unchanged.
//     If insideConstrainedOut was false, implication is vacuously true.
//   - When next == "<<": we set insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by precondition. Invariant satisfied.
//   - When we call OpenConstrainedSpan (budget exceeded): returns insideOut=true, currentOut=[].
//     parser.IsValidPrefix([]) holds. Invariant satisfied.
//   - EOS: break, no state change.
//
// Phase 2 (constrained loop):
//   Per iteration:
//   - CloseSpanIfComplete: either closes (insideConstrainedOut=false, implication vacuous,
//     currentConstrainedOut=[] preserved) or no-op (state unchanged, invariant preserved by IH).
//   - ConstrainedStep: returns a parser-valid token or EOS. The token is valid next at
//     currentConstrainedOut, so AppendConstrainedToken extends the valid prefix, maintaining
//     parser.IsValidPrefix(currentConstrainedOut + [next]) by definition of ValidPrefix.
//   - EOS path: CloseSpanIfComplete closes or no-ops; then break. Both paths preserve invariant.
//
// Phase 3 (CloseSpanWithinBudget):
//   Postcondition: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Invariant trivially preserved.
//
// progress: |generated| <= |generatedPrefix| + steps
//
// Phase 1:
//   Each loop iteration: UnconstrainedStep costs +1 step, appends at most 1 token (0 if EOS).
//   OpenConstrainedSpan: +1 step, appends "<<" (1 token). Total: steps+=1, |generated|+=1.
//   So after k iterations: |generated| <= |generatedPrefix| + k = |generatedPrefix| + steps. ✓
//
// Phase 2:
//   Per iteration: CloseSpanIfComplete costs +1 step, appends at most 1 token (">>").
//   If not closed: ConstrainedStep costs +1 step, AppendConstrainedToken appends at most 1 token.
//   Total per non-EOS iteration: steps += 2 (CloseSpanIfComplete + ConstrainedStep),
//   |generated| grows by at most 2 (">>" if closed + token if not closed).
//   Wait, if CloseSpanIfComplete fires, we break/continue (not calling ConstrainedStep).
//   So per iteration: 1 or 2 steps, 1 or 2 token growth. Both cases: |generated| <= |generatedPrefix| + steps. ✓
//   EOS path: CloseSpanIfComplete +1 step. steps+=1, |generated|+=at most 1. ✓
//
// Phase 3:
//   CloseSpanWithinBudget with budget = maxSteps - steps ensures:
//   |generatedOut| <= |generated| + (maxSteps - steps) <= |generatedPrefix| + steps + (maxSteps - steps)
//   = |generatedPrefix| + maxSteps. We set steps := maxSteps, so cost = maxSteps. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string := "Solve step by step. At the very end, write your final answer inside << >> using ONLY plain variable names (no curly braces) and operators +, -, *, /, //, %. Include ALL numeric variables from the problem. Do NOT include currency symbols, unit names, or format strings in the expression. Examples: <<n * price - discount>>, <<total - n1 + n2>>, <<base * rate // 100>>. Write exactly ONE expression inside << >>.";
  helpers.AppendTaskGuidance(lm, guidance);

  var steps: nat := 0;
  // Reasoning budget: 2/3 of maxSteps for free reasoning (matches best attempt 27)
  var reasoningBudget: nat := (maxSteps * 2) / 3;

  // Phase 1: Free generation until "<<" appears or reasoning budget exhausted
  while steps < maxSteps && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Check if we've hit the reasoning budget - force span open
    if steps >= reasoningBudget {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      break;
    }

    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }

  // Phase 2: Constrained generation inside the span
  // Use CloseSpanIfComplete FIRST each iteration to close as soon as expression is complete
  while steps < maxSteps && insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Reserve budget for CloseSpanWithinBudget (at least 30 steps)
    if steps + 30 >= maxSteps {
      break;
    }

    // Try to close if expression is already complete
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      break;
    }

    // Check budget again after CloseSpanIfComplete
    if steps >= maxSteps {
      break;
    }

    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    steps := steps + 1;

    if next == eosToken {
      // EOS: try to close if complete, then exit
      if steps < maxSteps {
        var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
        steps := steps + 1;
        if closed2 {
          generated := cg2;
          insideConstrainedOut := ci2;
          currentConstrainedOut := cc2;
        }
      }
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }

  // Phase 3: Force close if still inside span with remaining budget
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}
